{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table redtape_db.maplemonk.redtape_db_sellthrough as select c.*, d.sale_quantity, d.sale_value, e.return_quantity, e.return_value from (select week_start - 7 as week_start, month_start, order_date, category_mapped, division, gender, replace(SKU,\'`\',\'\') sku, REGEXP_REPLACE(replace(SKU,\'`\',\'\'), \'-[^-]*$\', \'\') article, sum(\"Available Quantity\") closing_inventory from (select s.* ,pgd.division ,pgd.gender ,coalesce(pma.category,pmf.category,pmac.category) category_mapped from (select m.*,a.week_start,a.month_start,a.order_date from ( select distinct order_date::date as order_date, date_trunc(week, order_date::date) as week_start, date_trunc(month, order_date::date) as month_start from redtape_db.maplemonk.redtape_db_sales_consolidated ) a left join redtape_db.maplemonk.easyecom_redtape_inventory_snapshot m on a.week_start = m.\"Report Generated Date\"::date + 1 where m.\"Report Generated Date\"::date is not null) s left join ( select * from (select *, row_number() over (partition by code order by 1) rw from redtape_db.maplemonk.product_mapping_gender_division )where rw=1 ) pgd on upper(left(replace(s.SKU,\'`\',\'\'),3)) = pgd.code left join (select * from (select code, \"FOR SELL THRU\" category, row_number() over (partition by code order by 1) rw from redtape_db.maplemonk.product_mapping_apparel )where rw = 1 ) pma on upper(left(replace(s.SKU,\'`\',\'\'),3)) = pma.code left join ( select * from (select code, gategory category, row_number() over (partition by code order by 1) rw from redtape_db.maplemonk.product_mapping_footwear where rw = 1 on upper(left(replace(s.SKU,\'`\',\'\'),3)) = pmf.code left join (select * from (select code, category, row_number() over (partition by code order by 1) rw from redtape_db.maplemonk.product_mapping_accessories) where rw = 1) pmac on upper(left(replace(s.SKU,\'`\',\'\'),3)) = pmac.code) group by 1,2,3,4,5,6,7,8) c left join (select category_mapped, division,gender,sku, order_date::date as order_date, date_trunc(week, order_date::date) as week_start, date_trunc(month, order_date::date) as month_start, sum(quantity) sale_quantity, sum(selling_price) sale_value, from redtape_db.maplemonk.redtape_db_sales_consolidated group by 1,2,3,4,5,6,7,8 ) d on c.gender = d.gender and c.division = d.division and c.category_mapped = d.category_mapped and c.week_start = d.week_start and c.month_start = d.month_start and c.order_date = d.order_date and c.sku = d.sku left join (select category_mapped,division,gender, sku,return_date::date as order_date, date_trunc(week, return_date::date) as week_start, date_trunc(month, return_date::date) as month_start, sum(total_returned_quantity) return_quantity, sum(TOTAL_RETURN_AMOUNT) return_value, from redtape_db.maplemonk.redtape_db_returns_consolidated group by 1,2,3,4,5,6,7,8 ) e on c.gender = e.gender and c.division = e.division and c.category_mapped = e.category_mapped and c.week_start = e.week_start and c.month_start = e.month_start and c.order_date = e.order_date and c.sku = e.sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            